def backup(path):
    if path.exists():
        b = path.with_suffix(path.suffix + ".bak_v31")
        if not b.exists():
            shutil.copy2(path, b)

def install(rel, content):
    path = ROOT / rel
    path.parent.mkdir(parents=True, exist_ok=True)
    backup(path)
    path.write_text(content, encoding="utf-8")
    print("installed", rel)

def main():
    print("Applying Buster v3.1 AI OS patch...")
    for rel, content in FILES.items():
        install(rel, content)
    print("\nDone. Run: python main.py")
    print("Test: workspace, remember my browser is Firefox, index project, repo status, builder create a weather app")

if __name__ == "__main__":
    main()
